declare module 'aws-svg-icons' {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const value: any;
  export default value;
}
declare module 'aws-svg-icons/*' {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const value: any;
  export default value;
}
declare module 'aws-svg-icons/*/*.svg' {
  const value: string;
  export default value;
}
declare module 'aws-svg-icons/*/*.png' {
  const value: string;
  export default value; 
}
